function layoutPreviewUrl(id, category) {
	return `https://cdn.jsdelivr.net/gh/yang0/handraw-style@master/images/layouts/${FOLDER[category]}/${id}.webp`;
}
var LAYOUTS = layouts_default.map((item) => ({
	...item,
	previewUrl: layoutPreviewUrl(item.id, item.category)
}));
var LAYOUT_BY_ID = Object.fromEntries(LAYOUTS.map((l) => [l.id, l]));
function getLayout(id) {
	if (!id) return void 0;
	return LAYOUT_BY_ID[id];
}
function filterLayouts(opts) {
	const q = opts.query.trim().toLowerCase();
	return LAYOUTS.filter((l) => {
		if (opts.category !== "all" && l.category !== opts.category) return false;
		if (!q) return true;
		return l.id.toLowerCase().includes(q) || l.nameVi.toLowerCase().includes(q) || l.nameEn.toLowerCase().includes(q) || l.nameZh.includes(opts.query.trim()) || l.keywords.some((k) => k.toLowerCase().includes(q));
	});
}
/** Skill isolation block. Injected only because the style plate is attached. */
var ISOLATION_ZH = "所附图片仅用于参考画风。只提取参考图的风格特征，例如线条、笔触、媒介、材质、色彩倾向和整体视觉语言；不要使用、复制或延续参考图中的任何主体、人物、动物、服装、道具、动作、姿态、场景、背景、构图、布局、文字或故事。最终画面内容完全以用户提供的主题为准。";
